- die eigenen Eltern misshandeln, 4:36; 6:151; 17:23
- Pflichtgebete vernachlässigen oder aufgeben, 19:59-60
- Almosensteuer nicht zahlen, 41:6-7
- Mord, 6:151; 17:33
- einen Gläubigen vorsätzlich töten, 4:93
- Diebstahl, 5:38
- Betrug, 7:85; 11:85; 26:182-183; 83:1-6
- Lügen, 2:10; 9:77; 39:60
- über Allah lügen, 6:93; 29:68; 61:7
- verbotene sexuelle Beziehungen, 2:222; 17:32; 24:2; 25:68; 29:28-30
- falsche Anschuldigungen des Ehebruchs, 24:4-5
- Abfall vom Glauben, 2:217; 5:54
- Schweinefleisch und andere verbotene Speisen essen (Aas, Blut usw.), 5:3; 6:145
- Alkohol und Glücksspiel, 5:90-91
- Verleumdung, 49:11
- falsches Zeugnis, 22:30
- Zauberei, 2:102; 10:77; 20:69
Islamic months
- 1st Muharram sacred month; fast 9th (Tasu'a) and 10th (Ashura) sunnah 9:36
- 2nd Safar
- 3rd Rabi al-Awwal
- 4th Rabi al-Thani
- 5th Jumada al-Awwal
- 6th Jumada al-Thani
- 7th Rajab sacred month
- 8th Sha'ban fast most of month (sunnah)
- 9th Ramadan obligatory fasting; Laylat al-Qadr 2:183-185, 187; 97:1-5
- 10th Shawwal Eid al-Fitr (1st); six days sunnah fasting
- 11th Dhul Qa'dah sacred month
- 12th Dhul Hijjah best ten days of year; fast first 9 days (sunnah); Day of Arafah (9th); Eid al-Adha (10th) forbidden to fast; Ayyam al-Tashriq (11th-13th) forbidden to fast 2:196-203; 22:27-28
- Fast Mondays and Thursdays (sunnah)
- Fast white days 13th, 14th, 15th every month (Ayyam al-Bid)
- Hajj during Shawwal, Dhul Qaa'dah and 10 days of Dhul Hijjah of Dhul Hijjah 2:197
