- Er sagte: "Mein Herr, mache mir ein Zeichen." Er sagte: "Dein Zeichen ist, dass du nicht mit den Menschen sprechen wirst..." (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- So wende dein Gesicht zur Heiligen Moschee. Und wo immer ihr seid, wendet eure Gesichter zu ihr. (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- O Kinder Israels, gedenkt Meiner Gnade, die Ich euch erwiesen habe, und dass Ich euch vor den Welten ausgezeichnet habe. (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- Sieben fette Kühe, die von sieben mageren gefressen werden, und sieben grüne Ähren und andere dürre. (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- Und jede Gemeinschaft hat eine festgesetzte Frist; und wenn ihre Frist kommt, können sie sie weder um eine Stunde hinauszögern noch vorverlegen. (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- (Das) worüber ein anderer Name als Allah ausgerufen wurde. Wer aber gezwungen wird, ohne Auflehnung und ohne Übertretung, so... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
- Und wenn ihnen gesagt wird: "Folgt dem, was Allah herabgesandt hat", sagen sie: "Nein, wir folgen dem, was..." (وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا) 2:170; 31:21
- Er sagte: "O mein Volk, dient Allah; ihr habt keinen anderen Gott außer Ihm. Wollt ihr denn nicht (Ihn) fürchten?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23
