- Derjenige, der die Himmel und die Erde erschaffen hat, ist fähig, ihresgleichen zu erschaffen. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
